use gpui::{Context, Window, div, prelude::*};
use gpui_audio_kit::audio::volume_knob::VolumeKnob;
use std::cell::RefCell;
use std::rc::Rc;
use std::sync::Arc;
use std::sync::atomic::{AtomicUsize, Ordering};

/// View that tracks value changes
pub(super) struct VolumeChangeTestView {
    pub(super) value: Rc<RefCell<f32>>,
    pub(super) change_count: Arc<AtomicUsize>,
}

impl Render for VolumeChangeTestView {
    fn render(&mut self, _window: &mut Window, _cx: &mut Context<Self>) -> impl IntoElement {
        let current_value = *self.value.borrow();
        let value_rc = self.value.clone();
        let change_count = self.change_count.clone();

        div().size_full().child(
            VolumeKnob::new()
                .id("change-test-knob")
                .value(current_value)
                .label("VOL")
                .on_change(move |new_val, _window, _cx| {
                    *value_rc.borrow_mut() = new_val;
                    change_count.fetch_add(1, Ordering::SeqCst);
                }),
        )
    }
}
